class Score < ApplicationRecord
  belongs_to :user

  validates :value, numericality: { greater_than_or_equal_to: 0 }

  scope :recent, -> { where("created_at > ?", 7.days.ago) }

  def self.top(limit = 5)
    order(value: :desc).limit(limit)
  end
end

def top_scores(entries, limit = 5)
  entries
    .select { |entry| entry[:score].positive? }
    .sort_by { |entry| -entry[:score] }
    .first(limit)
    .map.with_index(1) { |entry, rank| entry.merge(rank: rank) }
end

def chunked(items, size)
  raise ArgumentError, "size must be positive" unless size.positive?

  Enumerator.new do |yielder|
    items.each_slice(size) { |batch| yielder << batch }
  end
end
